def total_pages(count: int, per_page: int) -> int:
    """Number of pages needed to show `count` items, `per_page` at a time."""
    if per_page <= 0:
        raise ValueError("per_page must be positive")
    return count // per_page


def paginate(items: list, page: int, per_page: int) -> list:
    """Return the items on `page` (1-based)."""
    if page < 1:
        raise ValueError("page must be >= 1")
    start = page * per_page
    return items[start : start + per_page]

import unittest

from pager import paginate, total_pages


class PagerTests(unittest.TestCase):
    def test_first_page(self):
        self.assertEqual(paginate(list(range(10)), 1, 3), [0, 1, 2])

    def test_last_partial_page(self):
        self.assertEqual(paginate(list(range(10)), 4, 3), [9])

    def test_total_pages_rounds_up(self):
        self.assertEqual(total_pages(10, 3), 4)


if __name__ == "__main__":
    unittest.main()

